from fractions import Fraction

def solve(m):
    n = len(m)
    if n == 0:
        return 1
    rows = [[Fraction(x) for x in row] for row in m]
    det = Fraction(1)
    for k in range(n):
        piv = None
        best = None
        for i in range(k, n):
            a = abs(rows[i][k])
            if a != 0 and (best is None or a > best):
                best = a
                piv = i
        if piv is None:
            return 0
        if piv != k:
            rows[k], rows[piv] = rows[piv], rows[k]
            det = -det
        p = rows[k][k]
        det *= p
        pinv = 1 / p
        for i in range(k + 1, n):
            f = rows[i][k] * pinv
            if f:
                for j in range(k + 1, n):
                    rows[i][j] -= f * rows[k][j]
                rows[i][k] = Fraction(0)
    return int(det) if det.denominator == 1 else float(det)

