def solve(s):
    # sliding window using dict of next start position for each character
    last = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        # if character seen and its next-start index exceeds current start, move start
        if ch in last and last[ch] > start:
            start = last[ch]
        # length of current window
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
        # store index after current position as possible new start
        last[ch] = i + 1
    return max_len

