def solve(s):
    """Return True if brackets in s are balanced and properly nested.
    Handles only strings; non‑string inputs return False.
    Considers (), [], {} and ignores all other characters.
    """
    if not isinstance(s, str):
        return False
    stack = []
    opening = "([{"
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack

