def solve(n):
    """Return count of prime numbers strictly less than n.
    Handles integer and numeric inputs; non‑numeric returns 0.
    Uses a memory‑efficient approach: for moderate n (<=2_000_000) a sieve;
    for larger n falls back to trial division to avoid large allocations.
    """
    # Validate and coerce input
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Use sieve for reasonable size to stay fast and low memory
    MAX_SIEVE = 2_000_000
    if n <= MAX_SIEVE:
        limit = n
        is_prime = bytearray(b'\x01') * limit
        is_prime[0:2] = b'\x00\x00'
        import math
        for p in range(2, int(math.isqrt(limit)) + 1):
            if is_prime[p]:
                step = p
                start = p * p
                is_prime[start:limit:step] = b'\x00' * ((limit - start - 1) // step + 1)
        return sum(is_prime)
    # Fallback trial division for larger n
    def is_prime_num(x):
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        import math
        r = int(math.isqrt(x))
        for d in range(3, r + 1, 2):
            if x % d == 0:
                return False
        return True
    count = 0
    for i in range(2, n):
        if is_prime_num(i):
            count += 1
    return count

