def solve(path):
    """Simplify an absolute Unix path.
    Resolves '.' and '..', collapses multiple slashes, and removes trailing slash.
    The result is '/' for the root.
    """
    if not path:
        return '/'  # treat empty as root maybe
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

