def solve(matrix):
    from fractions import Fraction
    # Empty matrix has determinant 1 per spec
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix not square')
    # Convert to Fractions for exact arithmetic
    a = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # Find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det *= -1
        piv_val = a[i][i]
        det *= piv_val
        # Normalize row i
        for j in range(i, n):
            a[i][j] /= piv_val
        # Eliminate below
        for k in range(i+1, n):
            factor = a[k][i]
            if factor != 0:
                for j in range(i, n):
                    a[k][j] -= factor * a[i][j]
    # det is Fraction, should be integer
    return int(det)

