def solve(matrix):
    """Return the determinant of a square matrix of integers.
    Implements the Bareiss algorithm (fraction‑free Gaussian elimination)
    which yields an exact integer result for integer matrices.
    """
    n = len(matrix)
    if n == 0:
        return 1  # determinant of 0x0 matrix is conventionally 1
    # Make a copy to avoid mutating input
    A = [list(row) for row in matrix]
    det = 1
    for k in range(n - 1):
        # Find pivot; if zero, swap with a lower row
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det = -det
        pivot = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // (A[k - 1][k - 1] if k > 0 else 1)
        # Zero out the column below pivot
        for i in range(k + 1, n):
            A[i][k] = 0
    det *= A[n - 1][n - 1]
    return det

